contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount > 0, "amount must be positive");
        if (address(this).balance < amount) {
            require(msg.value >= amount - address(this).balance, "insufficient ether for top up");
        }

        uint beforeContractBalance = address(c).balance;
        uint beforeUserBalance = c.getBalance(address(this));

        c.addToBalance{value: amount}();

        uint midUserBalance = c.getBalance(address(this));
        uint midContractBalance = address(c).balance;

        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterUserBalance = c.getBalance(address(this));
        uint afterContractBalance = address(c).balance;

        assert(reverted == (midContractBalance < midUserBalance) ||
               (!reverted &&
                afterUserBalance == 0 &&
                midContractBalance >= midUserBalance &&
                afterContractBalance + midUserBalance == midContractBalance &&
                address(this).balance >= amount));
    }

    receive() external payable {}
}

